      "المعامل $a$ يحدد سعة الاقتران الجيبي وتساوي قيمته المطلقة $|a|$، وهو المسؤول عن التوسيع أو التضييق الرأسي للمنحنى.",
      "النقاط المفتاحية تشمل نقاط تقاطع الاقتران الجيبي مع المحور $x$ والنقاط العظمى والصغرى، وتُستخدم لتسهيل عملية التمثيل البياني."
