      "يكون الاقتران كثير الحدود متزايدًا في الفترة المفتوحة إذا كانت إشارة مشتقته الأولى موجبة تمامًا.",
      "يكون الاقتران كثير الحدود متناقصًا في الفترة المفتوحة إذا كانت إشارة مشتقته الأولى سالبة تمامًا.",
      "تُصنف النقطة الحرجة كعظمى محلية إذا تغير سلوك الاقتران حولها من التزايد إلى التناقص (تغير إشارة المشتقة من الموجب إلى السالب).",
