        "back": "أولاً: إيجاد المشتقة الأولى للاقتران $f'(x)$. ثانيًا: مساواة المشتقة بالصفر وحل المعادلة الناتجة لإيجاد قيم $x$ الحرجة. ثالثًا: تعويض قيم $x$ الحرجة في الاقتران الأصلي $f(x)$ لإيجاد الإحداثي الصادي وتشكيل الزوج المرتب $(x, f(x))$.",
