        "back": "القيمة الحرجة هي $x = 3$ لأنها تصفر المشتقة ($f'(x) = 2x - 6 = 0$). والنقطة الحرجة هي $(3, 0)$ بعد تعويض القيمة الحرجة في الاقتران الأصلي: $f(3) = 3^2 - 6(3) + 9 = 0$.",
